28	/**
29	 * Canonical address normalization shared by the create pipeline: {@link NormalizeAddress} stores and
30	 * returns the normalized form and {@link HouseholdNormalizer} compares addresses by it. Not a pipeline
31	 * step, so it is free to expose plain helpers.
32	 */
33	public final class AddressNormalizer {
34	
35	    /** Common street-type abbreviations expanded to their full word (keys are already upper-cased). */
36	    private static final Map<String, String> ABBREVIATIONS = Map.of(
37	            "ST", "STREET",
38	            "RD", "ROAD",
39	            "AVE", "AVENUE");
40	
41	    private AddressNormalizer() {
42	    }
43	
44	    /**
45	     * Normalizes an address to its canonical stored/compared form: outer whitespace trimmed, internal
46	     * runs of whitespace collapsed to a single space, upper-cased, and common street-type
47	     * abbreviations expanded as whole words ({@code ST}&rarr;{@code STREET}, {@code RD}&rarr;{@code
48	     * ROAD}, {@code AVE}&rarr;{@code AVENUE}). A {@code null} or blank address normalizes to an empty
49	     * string. Idempotent: normalizing an already-normalized address returns it unchanged.
50	     */
51	    public static String normalize(String address) {
52	        if (address == null) {
53	            return "";
54	        }
55	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
56	        if (collapsed.isEmpty()) {
57	            return "";
58	        }
59	        String[] tokens = collapsed.split(" ");
60	        StringBuilder result = new StringBuilder(collapsed.length());
61	        for (int i = 0; i < tokens.length; i++) {
62	            if (i > 0) {
63	                result.append(' ');
64	            }
65	            result.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
66	        }
67	        return result.toString();
68	    }
69	}
