190	package org.springframework.samples.petclinic.rest.function.owner;
191	
192	import java.util.LinkedHashMap;
193	import java.util.Map;
194	
195	/**
196	 * Canonical telephone normalization shared by the create pipeline: {@link NormalizeTelephone} stores
197	 * the E.164 form, {@link IdentityKey} uses it for the telephone part of the duplicate key and
198	 * {@link ValidateTelephoneLength} checks its national-number length. Not a pipeline step, so it is
199	 * free to expose plain helpers.
200	 */
201	public final class TelephoneNormalizer {
202	
203	    /** Minimum digits after the '+' for a valid E.164 number. */
204	    private static final int MIN_E164_DIGITS = 8;
205	
206	    /** Maximum digits after the '+' for a valid E.164 number. */
207	    private static final int MAX_E164_DIGITS = 15;
208	
209	    /** Default country code assumed when no leading '+' is present. */
210	    private static final String DEFAULT_COUNTRY_CODE = "61";
211	
212	    /**
213	     * Required national-number digit count per E.164 country code. Ordered longest code first so
214	     * {@link #hasValidNationalLength(String)} matches the most specific prefix (e.g. '61' before '1').
215	     */
216	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY = new LinkedHashMap<>();
217	
218	    static {
219	        NATIONAL_LENGTH_BY_COUNTRY.put("61", 9); // Australia
220	        NATIONAL_LENGTH_BY_COUNTRY.put("1", 10); // NANP (e.g. US)
221	    }
222	
223	    private TelephoneNormalizer() {
224	    }
225	
226	    /**
227	     * Converts a raw telephone to canonical E.164 form, or returns {@code null} when it cannot form a
228	     * valid E.164 number. A leading '+' and country code are kept when present; otherwise the default
229	     * country code '+61' is assumed and a single leading '0' is dropped from the national digits.
230	     * Spaces, dashes and brackets (any non-digit) are stripped. The result must have 8 to 15 digits
231	     * after the '+'.
232	     */
233	    public static String toE164(String telephone) {
234	        if (telephone == null) {
235	            return null;
236	        }
237	        boolean hasCountryCode = telephone.trim().startsWith("+");
238	        String digits = telephone.replaceAll("\\D", "");
239	        if (!hasCountryCode) {
240	            if (digits.startsWith("0")) {
241	                digits = digits.substring(1);
242	            }
243	            digits = DEFAULT_COUNTRY_CODE + digits;
244	        }
245	        if (digits.length() < MIN_E164_DIGITS || digits.length() > MAX_E164_DIGITS) {
246	            return null;
247	        }
248	        return "+" + digits;
249	    }
250	
251	    /** Size of each national-digit group in the human-readable display form. */
252	    private static final int DISPLAY_GROUP_SIZE = 3;
253	
254	    /**
255	     * Formats a canonical E.164 number for humans as its country code, a space, then the national
256	     * digits grouped in threes (e.g. '+61412345678' -&gt; '+61 412 345 678'). The country code is
257	     * identified from {@link #NATIONAL_LENGTH_BY_COUNTRY} (longest match first); a number whose
258	     * country code has no configured rule simply has all its digits grouped after the '+'. Expects
259	     * the canonical form produced by {@link #toE164(String)}; a value not in that form is returned
260	     * unchanged.
261	     */
262	    public static String toDisplay(String e164) {
263	        if (e164 == null || !e164.startsWith("+")) {
264	            return e164;
265	        }
266	        String digits = e164.substring(1);
267	        for (String countryCode : NATIONAL_LENGTH_BY_COUNTRY.keySet()) {
268	            if (digits.startsWith(countryCode)) {
269	                return "+" + countryCode + " " + groupInThrees(digits.substring(countryCode.length()));
270	            }
271	        }
272	        return "+" + groupInThrees(digits);
273	    }
274	
275	    /** Splits a run of digits into space-separated groups of {@link #DISPLAY_GROUP_SIZE}. */
276	    private static String groupInThrees(String digits) {
277	        StringBuilder grouped = new StringBuilder();
278	        for (int i = 0; i < digits.length(); i++) {
279	            if (i > 0 && i % DISPLAY_GROUP_SIZE == 0) {
280	                grouped.append(' ');
281	            }
282	            grouped.append(digits.charAt(i));
283	        }
284	        return grouped.toString();
285	    }
286	
287	    /**
288	     * Whether an E.164 number's national-number length matches what its country code requires (e.g.
289	     * '+61' expects 9 national digits, '+1' expects 10). Numbers whose country code has no configured
290	     * rule are accepted, so this only rejects a wrong length for a known country. Expects the canonical
291	     * form produced by {@link #toE164(String)}.
292	     */
293	    public static boolean hasValidNationalLength(String e164) {
294	        if (e164 == null || !e164.startsWith("+")) {
295	            return false;
296	        }
297	        String digits = e164.substring(1);
298	        for (Map.Entry<String, Integer> rule : NATIONAL_LENGTH_BY_COUNTRY.entrySet()) {
299	            String countryCode = rule.getKey();
300	            if (digits.startsWith(countryCode)) {
301	                return digits.length() - countryCode.length() == rule.getValue();
302	            }
303	        }
304	        return true;
305	    }
306	}
