586	package org.springframework.samples.petclinic.rest.function.owner;
587	
588	import org.springframework.samples.petclinic.model.Owner;
589	import org.springframework.samples.petclinic.util.Sha256;
590	
591	/**
592	 * Canonical household identity shared by the create pipeline. A household is keyed on
593	 * <em>last name plus postcode</em>: the last name is compared case-insensitively with runs of
594	 * whitespace collapsed to a single space and outer whitespace trimmed, and the postcode is compared
595	 * verbatim. Owners with equal keys are the same household and therefore share the same
596	 * {@link #id(String, String) household id}, which is a pure, stable function of those two fields — so
597	 * it is stamped on every owner at creation ({@link AssignHousehold}) rather than looked up.
598	 *
599	 * <p>The id feeds every rule that keys off the household: the duplicate block
600	 * ({@link EnsureUniqueIdentity}), the household-size count ({@link CountHousehold}) and the
601	 * possible-duplicate flag ({@link FlagPossibleDuplicate}) all decide membership with
602	 * {@link #belongsTo(Owner, String)}. Not a pipeline step, so it is free to expose plain helpers.
603	 */
604	public final class HouseholdNormalizer {
605	
606	    private HouseholdNormalizer() {
607	    }
608	
609	    /**
610	     * The stable household identifier for an owner: the first 12 hex characters of the SHA-256 of the
611	     * household {@link #key(String, String) key}. Owners with equal keys share the same id, and the id
612	     * never changes for a given (last name, postcode), so it can be recomputed rather than stored.
613	     */
614	    public static String id(String lastName, String postcode) {
615	        return Sha256.prefix(key(lastName, postcode), 12);
616	    }
617	
618	    /**
619	     * Builds the canonical household key: the normalized last name and the postcode joined by '|'.
620	     * Two owners belong to the same household when their keys are equal. Either field may be
621	     * {@code null}, which normalizes to an empty token.
622	     */
623	    public static String key(String lastName, String postcode) {
624	        return normalizeName(lastName) + "|" + orEmpty(postcode);
625	    }
626	
627	    /**
628	     * Whether {@code owner} belongs to the household identified by {@code householdId}, i.e. its own
629	     * (last name, postcode) hashes to that id. {@code false} when {@code householdId} is {@code null}.
630	     */
631	    public static boolean belongsTo(Owner owner, String householdId) {
632	        return householdId != null && householdId.equals(id(owner.getLastName(), owner.getPostcode()));
633	    }
634	
635	    /** Lower-cases and collapses whitespace to single spaces, trimming the ends; {@code null} → "". */
636	    private static String normalizeName(String value) {
637	        if (value == null) {
638	            return "";
639	        }
640	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
641	    }
642	
643	    private static String orEmpty(String value) {
644	        return value == null ? "" : value;
645	    }
646	}
