650	import org.springframework.samples.petclinic.model.Owner;
651	
652	/**
653	 * A derived, opaque summary of an owner's contact identity: the canonical telephone, the canonical
654	 * email (empty when absent) and the household id, joined by '|'.
655	 * {@link org.springframework.samples.petclinic.mapper.OwnerMapper} returns it on the response so a
656	 * client can compare owners at a glance. Duplicate detection itself keys off the household id alone
657	 * (see {@link EnsureUniqueIdentity}); this value simply surfaces the parts. Not a pipeline step, so it
658	 * exposes plain helpers.
659	 */
660	public final class IdentityKey {
661	
662	    private IdentityKey() {
663	    }
664	
665	    /** The identity key of an existing or freshly built owner. */
666	    public static String forOwner(Owner owner) {
667	        return of(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
668	    }
669	
670	    /**
671	     * Builds the identity key from its parts: the telephone in canonical E.164 form (see
672	     * {@link TelephoneNormalizer}), the email lower-cased or empty when absent or blank (see
673	     * {@link EmailNormalizer}) and the household id or empty when absent, separated by '|'.
674	     */
675	    public static String of(String telephone, String email, String householdId) {
676	        return normalizeTelephone(telephone) + "|" + normalizeEmail(email) + "|" + orEmpty(householdId);
677	    }
