679	    private static String normalizeTelephone(String telephone) {
680	        String e164 = TelephoneNormalizer.toE164(telephone);
681	        return e164 == null ? orEmpty(telephone) : e164;
682	    }
683	
684	    private static String normalizeEmail(String email) {
685	        return (email == null || email.isBlank()) ? "" : EmailNormalizer.normalize(email);
686	    }
687	
688	    private static String orEmpty(String value) {
689	        return value == null ? "" : value;
690	    }
