805	            if (HouseholdNormalizer.belongsTo(existing, householdId)
806	                    && !owner.getTelephone().equals(existing.getTelephone())) {
807	                if (match == null || existing.getId() < match.getId()) {
808	                    match = existing;
809	                }
810	            }
811	        }
812	        if (match != null) {
813	            owner.setPossibleDuplicate(true);
814	            owner.setPossibleDuplicateOf(match.getId());
815	        }
816	    }
